INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6093519, 897272, 114225, '<td valign="top">Good idea, especially with getting depth to this photo. I do wish there were less noise, especially in the solid color areas.</td>', 'Good idea, especially with getting depth to this photo. I do wish there were less noise, especially in the solid color areas.', '2010-07-15 00:31:28.000000', NULL, 1),
(6093520, 897627, 114225, '<td valign="top">That''s a cool  structure. With what looks like a fish-eye lens, it does feel a bit faked (which if so, good job on that!).</td>', 'That''s a cool  structure. With what looks like a fish-eye lens, it does feel a bit faked (which if so, good job on that!).', '2010-07-15 00:32:35.000000', NULL, 1),
(6093521, 897316, 114225, '<td valign="top">Cute creations, and a fun setup. Good use of depth of field and nice lighting.</td>', 'Cute creations, and a fun setup. Good use of depth of field and nice lighting.', '2010-07-15 00:33:00.000000', NULL, 1),
(6093523, 897605, 114225, '<td valign="top">Reminds me of the winner of the second ever DPC challenge.I like the clarity of the cueball, but this the painted look of the racked balls is a little distracting. I wish either a larger or small DOF was used to ether show the entire scene in focus or really make the cue ball the subject.</td>', 'Reminds me of the winner of the second ever DPC challenge.I like the clarity of the cueball, but this the painted look of the racked balls is a little distracting. I wish either a larger or small DOF was used to ether show the entire scene in focus or really make the cue ball the subject.', '2010-07-15 00:35:13.000000', NULL, 1),
(6093524, 897351, 114225, '<td valign="top">Good idea for the challenge. Nice collection of globes. Only thing I don''t like is the bright reflections. IF you could have somehow diffused the light, I think the photo could have been more pleasant.</td>', 'Good idea for the challenge. Nice collection of globes. Only thing I don''t like is the bright reflections. IF you could have somehow diffused the light, I think the photo could have been more pleasant.', '2010-07-15 00:35:59.000000', NULL, 1),
(6093526, 896965, 114225, '<td valign="top">Good creativity for this challenge. Create details in the face.</td>', 'Good creativity for this challenge. Create details in the face.', '2010-07-15 00:36:22.000000', NULL, 1),
(6093527, 897208, 114225, '<td valign="top">Hopefully they don''t influence your scores, as the photo deserves more than that :)<br/>I really like the top spot lighting you used.</td>', 'Hopefully they don''t influence your scores, as the photo deserves more than that :)I really like the top spot lighting you used.', '2010-07-15 00:37:06.000000', NULL, 1),
(6093528, 897583, 114225, '<td valign="top">Great bubbles shot. Nice job getting a good reflection without a distracting background.</td>', 'Great bubbles shot. Nice job getting a good reflection without a distracting background.', '2010-07-15 00:37:55.000000', NULL, 1),
(6093531, 896971, 114225, '<td valign="top">These spheres look a bit stretched :)<br/>Nice clarity and colors in this photo.</td>', 'These spheres look a bit stretched :)Nice clarity and colors in this photo.', '2010-07-15 00:39:00.000000', NULL, 1),
(6093532, 897286, 114225, '<td valign="top">This perspective makes me dizzy! With a subject like that, it works. I don''t really count the pods as spheres though.</td>', 'This perspective makes me dizzy! With a subject like that, it works. I don''t really count the pods as spheres though.', '2010-07-15 00:39:46.000000', NULL, 1),
(6093534, 897257, 114225, '<td valign="top">Good clarity in the reflections, although we can see the photographer! It would have been great if you could have found an angle that kept you out of the shot.</td>', 'Good clarity in the reflections, although we can see the photographer! It would have been great if you could have found an angle that kept you out of the shot.', '2010-07-15 00:40:40.000000', NULL, 1),
(6093535, 897521, 114225, '<td valign="top">Good find for the challenge. However, the photo has a bit of a snapshot feel to it. I think if you could have played with composition a bit (maybe by getting closer and only including half the structure), it could have had more impact.</td>', 'Good find for the challenge. However, the photo has a bit of a snapshot feel to it. I think if you could have played with composition a bit (maybe by getting closer and only including half the structure), it could have had more impact.', '2010-07-15 00:42:03.000000', NULL, 1),
(6093536, 896921, 114225, '<td valign="top">Really cool photo. I like the sun in the corner and how you can really feel the bubbles just floating through the air.</td>', 'Really cool photo. I like the sun in the corner and how you can really feel the bubbles just floating through the air.', '2010-07-15 00:42:51.000000', NULL, 1),
(6093537, 897263, 114225, '<td valign="top">I get what you were going for, and it''s a very nice photo overall, but I don''t see it as really fitting the challenge.</td>', 'I get what you were going for, and it''s a very nice photo overall, but I don''t see it as really fitting the challenge.', '2010-07-15 00:43:42.000000', NULL, 1),
(6093539, 897074, 114225, '<td valign="top">I have looked at this photo for a bit, and I cannot seem to find any spheres within it.<br/>Too bad, as it''s a really nice photo with good balance of composition.</td>', 'I have looked at this photo for a bit, and I cannot seem to find any spheres within it.Too bad, as it''s a really nice photo with good balance of composition.', '2010-07-15 00:44:38.000000', NULL, 1),
(6093540, 897422, 114225, '<td valign="top">Great capture.Good textures in the feathers and really nice lighting.</td>', 'Great capture.Good textures in the feathers and really nice lighting.', '2010-07-15 00:45:31.000000', NULL, 1),
(6093541, 897402, 114225, '<td valign="top">Unfortunately, a cylinder isn''t a sphere. Good attempt thought, as you used the rule of thirds well. One suggestion for overall improvement it to watch the background. The buildings are very distracting, and it feels like if you moved a bit to the left you wouldn''t see them in the photo.</td>', 'Unfortunately, a cylinder isn''t a sphere. Good attempt thought, as you used the rule of thirds well. One suggestion for overall improvement it to watch the background. The buildings are very distracting, and it feels like if you moved a bit to the left you wouldn''t see them in the photo.', '2010-07-15 00:47:39.000000', NULL, 1),
(6093543, 897595, 114225, '<td valign="top">Nice job capturing the texture of the leather. I like the side lighting, it adds a bit of drama to the photo.</td>', 'Nice job capturing the texture of the leather. I like the side lighting, it adds a bit of drama to the photo.', '2010-07-15 00:48:41.000000', NULL, 1),
(6093544, 897284, 114225, '<td valign="top">Cool find. Good use of depth of field to really draw the viewer''s eyes in.</td>', 'Cool find. Good use of depth of field to really draw the viewer''s eyes in.', '2010-07-15 00:49:22.000000', NULL, 1),
(6093547, 897235, 114225, '<td valign="top">Great job capturing two complete opposites in a single photo. Nice overall clarity, however the relatively high noise is reducing that slightly.</td>', 'Great job capturing two complete opposites in a single photo. Nice overall clarity, however the relatively high noise is reducing that slightly.', '2010-07-15 00:50:31.000000', NULL, 1),
(6093549, 897593, 114225, '<td valign="top">Simple, but nice. Good lighting used here.</td>', 'Simple, but nice. Good lighting used here.', '2010-07-15 00:50:54.000000', NULL, 1),
(6093550, 897422, 117887, '<td valign="top">love the detail in his feathers.  i can almost feel him exhaling at me to get away from his blueberry.  10.</td>', 'love the detail in his feathers.  i can almost feel him exhaling at me to get away from his blueberry.  10.', '2010-07-15 00:51:36.000000', NULL, 1),
(6093551, 896657, 114225, '<td valign="top">Nice creative composition for this photo. I don''t really care for the watercolor effect in most photo, but for this one your subject handles it well.</td>', 'Nice creative composition for this photo. I don''t really care for the watercolor effect in most photo, but for this one your subject handles it well.', '2010-07-15 00:51:52.000000', NULL, 1),
(6093553, 897602, 117887, '<td valign="top">i love it when someone names their pictures after math terms.  nerd!  (plus this is a great shot!) would have given you a 10 but the cubs ball is turned a little too much but the rest are all facing the same direction. 9</td>', 'i love it when someone names their pictures after math terms.  nerd!  (plus this is a great shot!) would have given you a 10 but the cubs ball is turned a little too much but the rest are all facing the same direction. 9', '2010-07-15 00:53:18.000000', NULL, 1),
(6093554, 896457, 114225, '<td valign="top">Nice textures in the peach. Good use of blurred background to really bring out the subject. A tiny thing, but I maybe have chosen a crop that didn''t include the light spots in the upper and lower left hand corners.</td>', 'Nice textures in the peach. Good use of blurred background to really bring out the subject. A tiny thing, but I maybe have chosen a crop that didn''t include the light spots in the upper and lower left hand corners.', '2010-07-15 00:53:34.000000', NULL, 1),
(6093555, 897403, 117887, '<td valign="top">i like the way the lighting comes from the bottom of this picture.  that is a nice change.</td>', 'i like the way the lighting comes from the bottom of this picture.  that is a nice change.', '2010-07-15 00:53:49.000000', NULL, 1),
(6093556, 897412, 114225, '<td valign="top">Great clarity in the plasma ball. The hands/face do add some interest to the photo as well, although I think it would have been just as cool without the person.</td>', 'Great clarity in the plasma ball. The hands/face do add some interest to the photo as well, although I think it would have been just as cool without the person.', '2010-07-15 00:54:23.000000', NULL, 1),
(6093557, 897426, 117887, '<td valign="top">it is a little too close/out of focus to me.  but, great idea!</td>', 'it is a little too close/out of focus to me.  but, great idea!', '2010-07-15 00:54:50.000000', NULL, 1),
(6093558, 897306, 114225, '<td valign="top">Very creative entry for this challenge. Excellent use of depth of field and very good detail.</td>', 'Very creative entry for this challenge. Excellent use of depth of field and very good detail.', '2010-07-15 00:55:03.000000', NULL, 1),
(6093560, 897491, 114225, '<td valign="top">Cool lighting in this photo. I have to imagine that was pretty tricky to get right.</td>', 'Cool lighting in this photo. I have to imagine that was pretty tricky to get right.', '2010-07-15 00:55:45.000000', NULL, 1),
(6093563, 897643, 114225, '<td valign="top">I like this photo. A bit abstract, and my interpretation is a planet in a far away galaxy.</td>', 'I like this photo. A bit abstract, and my interpretation is a planet in a far away galaxy.', '2010-07-15 00:56:55.000000', NULL, 1),
(6093564, 897605, 117887, '<td valign="top">none of the balls are in focus.  i think if the colored balls were pulled down some it would have been a little more centered.  i LOVE The idea, though.  it looks like a great shot for the next time i visit my in-laws house!  i bet this was ridiculously hard to get since most pool tables are horribly lit and your lighting is actually pretty good!  i like the way a little bit of the neon light is reflected on the balls...</td>', 'none of the balls are in focus.  i think if the colored balls were pulled down some it would have been a little more centered.  i LOVE The idea, though.  it looks like a great shot for the next time i visit my in-laws house!  i bet this was ridiculously hard to get since most pool tables are horribly lit and your lighting is actually pretty good!  i like the way a little bit of the neon light is reflected on the balls...', '2010-07-15 00:57:16.000000', NULL, 1),
(6093566, 897091, 117887, '<td valign="top">this seems out of focus to me, but i love the color contrast of the purple and mustard with white!</td>', 'this seems out of focus to me, but i love the color contrast of the purple and mustard with white!', '2010-07-15 00:57:55.000000', NULL, 1),
(6093569, 896812, 117887, '<td valign="top">love the title but the photo seems really dark.</td>', 'love the title but the photo seems really dark.', '2010-07-15 00:58:34.000000', NULL, 1),
(6093570, 897398, 117887, '<td valign="top">is that an egg?  like your DOF.</td>', 'is that an egg?  like your DOF.', '2010-07-15 00:59:04.000000', NULL, 1),
(6093571, 897531, 114225, '<td valign="top">Good idea with the yarn balls. Some suggestions for improvements:<br/>Looks like you use on camera flash that is providing some un-pleasing reflections and shadows.<br/>Might want to focus more on the yarn balls, and less on the chair (find a different setting that is less distracting).</td>', 'Good idea with the yarn balls. Some suggestions for improvements:Looks like you use on camera flash that is providing some un-pleasing reflections and shadows.Might want to focus more on the yarn balls, and less on the chair (find a different setting that is less distracting).', '2010-07-15 00:59:07.000000', NULL, 1),
(6093572, 896432, 114225, '<td valign="top">Good composition and lighting used in this photo. Also very good sharpness.</td>', 'Good composition and lighting used in this photo. Also very good sharpness.', '2010-07-15 00:59:36.000000', NULL, 1),
(6093574, 897399, 114225, '<td valign="top">I like it. Good clarity for a water shot.</td>', 'I like it. Good clarity for a water shot.', '2010-07-15 01:00:11.000000', NULL, 1),
(6093575, 897518, 117887, '<td valign="top">i can see you and your suburbia in the reflection on the bubble!  :)  i love this shot. i take ones like this all the time with my children.  getting the moment when the bubble is blowing is hard to do!  i like your crop, also.</td>', 'i can see you and your suburbia in the reflection on the bubble!  :)  i love this shot. i take ones like this all the time with my children.  getting the moment when the bubble is blowing is hard to do!  i like your crop, also.', '2010-07-15 01:00:58.000000', NULL, 1),
(6093576, 897622, 114225, '<td valign="top">This is a really cool photo overall. Great use of vignetting and super color color tone. However, I don''t could this shape as a sphere.</td>', 'This is a really cool photo overall. Great use of vignetting and super color color tone. However, I don''t could this shape as a sphere.', '2010-07-15 01:01:04.000000', NULL, 1),
(6093577, 897539, 117887, '<td valign="top">you did a good job of not getting yourself in this reflecting ball!</td>', 'you did a good job of not getting yourself in this reflecting ball!', '2010-07-15 01:02:21.000000', NULL, 1),
(6093578, 897529, 114225, '<td valign="top">Nice colors to this droplet shot. Good timing with the concentric circles. There is a lot of noise which seems to be hurting the overall sharpness.</td>', 'Nice colors to this droplet shot. Good timing with the concentric circles. There is a lot of noise which seems to be hurting the overall sharpness.', '2010-07-15 01:02:34.000000', NULL, 1),
(6093579, 897568, 117887, '<td valign="top">i like the texture here.  guess you could have submitted this one to either category (spheres or rectangles).</td>', 'i like the texture here.  guess you could have submitted this one to either category (spheres or rectangles).', '2010-07-15 01:02:54.000000', NULL, 1),
(6093580, 897292, 114225, '<td valign="top">Nicely setup shot. Good colors and clean lines. I do like the effect used to give it a painted look.</td>', 'Nicely setup shot. Good colors and clean lines. I do like the effect used to give it a painted look.', '2010-07-15 01:03:18.000000', NULL, 1),
(6093582, 896971, 117887, '<td valign="top">i LOVE this one but i can see you in the water droplets!  i love your DOF.  i totally want a macro.  beautiful shot!  10</td>', 'i LOVE this one but i can see you in the water droplets!  i love your DOF.  i totally want a macro.  beautiful shot!  10', '2010-07-15 01:03:53.000000', NULL, 1),
(6093583, 897295, 114225, '<td valign="top">The lighting in this photo is very dramatic. The macro is done well with good composition. However, I don''t see any spheres in this photo.</td>', 'The lighting in this photo is very dramatic. The macro is done well with good composition. However, I don''t see any spheres in this photo.', '2010-07-15 01:04:12.000000', NULL, 1),
(6093584, 897238, 114225, '<td valign="top">Nice use of the pleasing morning sun. I like the top down perspective, and the good contrast of colors. Looks like the JPEG conversion created some color banding which isn''t pleasing.</td>', 'Nice use of the pleasing morning sun. I like the top down perspective, and the good contrast of colors. Looks like the JPEG conversion created some color banding which isn''t pleasing.', '2010-07-15 01:05:43.000000', NULL, 1),
(6093586, 896659, 114225, '<td valign="top">Good textures and lighting here. The photo has a bit of drama to it.</td>', 'Good textures and lighting here. The photo has a bit of drama to it.', '2010-07-15 01:06:14.000000', NULL, 1),
(6093587, 897304, 117887, '<td valign="top">shot is a little blurry - and, IMHO, would be more dramatic if maybe the bottom part was cropped off so that the berries were on the bottom 3rd rather than the center. i also tried to shoot (ripe) blueberries and i couldn''t get them in focus very easy.  could have been because my daughter was picking them and shaking the bush, though.  good luck!</td>', 'shot is a little blurry - and, IMHO, would be more dramatic if maybe the bottom part was cropped off so that the berries were on the bottom 3rd rather than the center. i also tried to shoot (ripe) blueberries and i couldn''t get them in focus very easy.  could have been because my daughter was picking them and shaking the bush, though.  good luck!', '2010-07-15 01:07:06.000000', NULL, 1),
(6093588, 896824, 114225, '<td valign="top">Does GBWN stand for anything?<br/>I like the composition used, with the wrist starting at the lower left corner and moving into the photo. Good use of non-distracting background.</td>', 'Does GBWN stand for anything?I like the composition used, with the wrist starting at the lower left corner and moving into the photo. Good use of non-distracting background.', '2010-07-15 01:07:33.000000', NULL, 1),
(6093590, 896965, 83104, '<td valign="top">Great capture of a jumping spider!</td>', 'Great capture of a jumping spider!', '2010-07-15 01:08:10.000000', NULL, 1),
(6093591, 896825, 114225, '<td valign="top">I really like the basic setup of this shot. Good clean lines and night lighting.</td>', 'I really like the basic setup of this shot. Good clean lines and night lighting.', '2010-07-15 01:08:25.000000', NULL, 1),
(6093593, 897208, 117887, '<td valign="top">i guess i don''t understand the picture.  it doesn''t appeal to me because it lacks a center (rather, it is off center and/or doesn''t use the rule of thirds).  and to my artist-side, i see that the red and blue make purple but i''m not sure about the yellow.  the colors are all bleeding/reflecting off each other in the picture (harsh light?) and the brown carpet doesn''t compliment the colors either.  on another note, your focus is very good and they are all positioned well, something that can be very tedious!</td>', 'i guess i don''t understand the picture.  it doesn''t appeal to me because it lacks a center (rather, it is off center and/or doesn''t use the rule of thirds).  and to my artist-side, i see that the red and blue make purple but i''m not sure about the yellow.  the colors are all bleeding/reflecting off each other in the picture (harsh light?) and the brown carpet doesn''t compliment the colors either.  on another note, your focus is very good and they are all positioned well, something that can be very tedious!', '2010-07-15 01:10:17.000000', NULL, 1),
(6093594, 897480, 117887, '<td valign="top">love the way i can see the hairs on the leaves!  and, your color choice for background.  great contrast yet complimentary all at the same time.  cropped well or framed well during composition also.</td>', 'love the way i can see the hairs on the leaves!  and, your color choice for background.  great contrast yet complimentary all at the same time.  cropped well or framed well during composition also.', '2010-07-15 01:11:57.000000', NULL, 1),
(6093595, 897257, 117887, '<td valign="top">i can see you in the reflection!</td>', 'i can see you in the reflection!', '2010-07-15 01:12:23.000000', NULL, 1),
(6093596, 897284, 117887, '<td valign="top">love the way you used your DOF (or macro? not sure) to focus in just on the eggs.  very nicely composed, but it creeps me out!  yuck.  i hope you stomped it when you were done!</td>', 'love the way you used your DOF (or macro? not sure) to focus in just on the eggs.  very nicely composed, but it creeps me out!  yuck.  i hope you stomped it when you were done!', '2010-07-15 01:13:17.000000', NULL, 1),
(6093599, 897415, 117887, '<td valign="top">seems like a lot of empty space at the bottom of the picture.  you were probably going for the bottle-reflection but it just seems top-heavy to me.  GREAT lighting though.</td>', 'seems like a lot of empty space at the bottom of the picture.  you were probably going for the bottle-reflection but it just seems top-heavy to me.  GREAT lighting though.', '2010-07-15 01:14:43.000000', NULL, 1),
(6093600, 896839, 117887, '<td valign="top">love the use of DOF here!</td>', 'love the use of DOF here!', '2010-07-15 01:15:06.000000', NULL, 1),
(6093601, 897376, 117887, '<td valign="top">i know you have no control over this, but a 90 degree angle on that pool edge would have been nice!  :)  lovely shot, lots of color!</td>', 'i know you have no control over this, but a 90 degree angle on that pool edge would have been nice!  :)  lovely shot, lots of color!', '2010-07-15 01:15:44.000000', NULL, 1),
(6093603, 896440, 117887, '<td valign="top">lovely composition!  love the focus on the front of the fly - my eyes are drawn right to his eyes!  wish the title was "eyes" of the hunter...</td>', 'lovely composition!  love the focus on the front of the fly - my eyes are drawn right to his eyes!  wish the title was "eyes" of the hunter...', '2010-07-15 01:16:48.000000', NULL, 1),
(6093604, 897280, 117887, '<td valign="top">beautiful!  i love photos with lighting from the bottom.  love the glistening background also.</td>', 'beautiful!  i love photos with lighting from the bottom.  love the glistening background also.', '2010-07-15 01:17:39.000000', NULL, 1),
(6093614, 897624, 88235, '<td valign="top">That''s pretty... what in the world is it?</td>', 'That''s pretty... what in the world is it?', '2010-07-15 01:25:03.000000', NULL, 1),
(6093615, 897316, 88235, '<td valign="top">lol! poor critter...</td>', 'lol! poor critter...', '2010-07-15 01:27:12.000000', NULL, 1),
(6093627, 897422, 63812, '<td valign="top">very good! a winner...vote 9</td>', 'very good! a winner...vote 9', '2010-07-15 01:47:50.000000', NULL, 1),
(6093628, 896919, 63812, '<td valign="top">I love it!</td>', 'I love it!', '2010-07-15 01:48:53.000000', NULL, 1),
(6093643, 896440, 63812, '<td valign="top">very good! 9</td>', 'very good! 9', '2010-07-15 02:08:12.000000', NULL, 1),
(6093671, 897622, 37252, '<td valign="top">Cool shot though technically they are not spheres</td>', 'Cool shot though technically they are not spheres', '2010-07-15 03:39:26.000000', NULL, 1),
(6093672, 896804, 103032, '<td valign="top">This pic really pops out.  Unbelievably sharp in image in the globe.  Love the star effect of the sun and the sun(?) at the 5 o''clock position on the edge of the globe.  I wonder if this is mycelium; he had a cool image like this previously.  definitely meets the challenge using a sphere and has a great image in it.</td>', 'This pic really pops out.  Unbelievably sharp in image in the globe.  Love the star effect of the sun and the sun(?) at the 5 o''clock position on the edge of the globe.  I wonder if this is mycelium; he had a cool image like this previously.  definitely meets the challenge using a sphere and has a great image in it.', '2010-07-15 03:40:17.000000', NULL, 1),
(6093673, 897602, 103032, '<td valign="top">Nice shadow box collection.  Like the patterns/lines of the horizontal shelves and the vertical dividers; the alignment of the golfballs and the dimples of the golfballs.  Cool perspective, patterns, and "spheres".  Cool picture.</td>', 'Nice shadow box collection.  Like the patterns/lines of the horizontal shelves and the vertical dividers; the alignment of the golfballs and the dimples of the golfballs.  Cool perspective, patterns, and "spheres".  Cool picture.', '2010-07-15 03:40:25.000000', NULL, 1),
(6093711, 897626, 40005, '<td valign="top">Nice idea ! I love it ! ...but lines on the bed disturb me a bit because they''re not completely horizontal...</td>', 'Nice idea ! I love it ! ...but lines on the bed disturb me a bit because they''re not completely horizontal...', '2010-07-15 06:48:43.000000', NULL, 1),
(6093713, 896918, 40005, '<td valign="top">Nice capture ! ...but a bit noisy at the bottom...</td>', 'Nice capture ! ...but a bit noisy at the bottom...', '2010-07-15 06:49:37.000000', NULL, 1),
(6093718, 897272, 40005, '<td valign="top">It would have been a really great shot for me with much less noise... Beautiful bubbles and transparency anyway !</td>', 'It would have been a really great shot for me with much less noise... Beautiful bubbles and transparency anyway !', '2010-07-15 06:55:49.000000', NULL, 1),
(6093849, 897257, 117474, '<td valign="top">Excellent image. One criticism is that I can see you in there. It might have been possible to remove yourself from the image and trigger the shutter remotely. The stand may have been obscured by other lines in the shot. It''s no big deal, though.<br/>I really like it. 10 :)</td>', 'Excellent image. One criticism is that I can see you in there. It might have been possible to remove yourself from the image and trigger the shutter remotely. The stand may have been obscured by other lines in the shot. It''s no big deal, though.I really like it. 10 :)', '2010-07-15 09:30:34.000000', NULL, 1),
(6093878, 897415, 97475, '<td valign="top">I think the bottle is too near to the edge. Pretty girl.</td>', 'I think the bottle is too near to the edge. Pretty girl.', '2010-07-15 10:10:40.000000', NULL, 1),
